/**
 * Script 2: runStory.ts
 * ─────────────────────────────────────────────────────────────────────────────
 * Autonomous test execution pipeline for a given Story ID:
 *   1. Load the manifest generated by analyzeStory.ts (or fetch fresh from ADO)
 *   2. Run corresponding Playwright tests via the CLI
 *   3. Parse the test results JSON
 *   4. Update the Excel file with Pass/Fail results and timestamps
 *   5. Upload the updated Excel back to the Azure DevOps User Story
 *   6. Post a final execution summary comment to the Work Item history
 *
 * Usage:
 *   npx ts-node -r tsconfig-paths/register scripts/runStory.ts <storyId> [options]
 *
 * Options:
 *   --project=chromium     Playwright project to run (default: chromium)
 *   --headed               Run in headed mode
 *   --no-excel             Skip Excel update
 *   --no-ado               Skip Azure DevOps update
 *   --dry-run              Parse results only, no ADO writes
 *   --url=https://...      Override target base URL
 */

import * as path from 'path';
import * as fs from 'fs';
import { spawnSync } from 'child_process';
import * as dotenv from 'dotenv';

dotenv.config({ path: path.resolve(__dirname, '../.env') });

import chalk from 'chalk';
import dayjs from 'dayjs';

import { AzureDevOpsClient }  from '../src/clients/azureDevOps.client';
import { ExcelReporter }      from '../src/reporters/excelReporter';
import { CreatedBug, TestExecutionRecord, StoryRunResult } from '../src/types/index';
import {
  buildPlaywrightSelectionArgs,
  mappedTestCases,
  parsePlaywrightReport,
  validateStoryManifest,
} from '../src/agents/storyExecution';
import {
  AZURE_DEVOPS_AREA_PATH,
  AZURE_DEVOPS_ITERATION_PATH,
  EXCEL_DIR,
} from '../config/env';

// ─── Types ────────────────────────────────────────────────────────────────────

interface RunOptions {
  storyId:    number;
  project:    string;
  headed:     boolean;
  updateExcel: boolean;
  updateAdo:   boolean;
  dryRun:     boolean;
  targetUrl?:  string;
}

// ─── CLI Argument Parsing ─────────────────────────────────────────────────────

function parseArgs(): RunOptions {
  const args = process.argv.slice(2);

  const storyArg = args.find((a) => /^\d+$/.test(a));
  if (!storyArg) {
    console.error(
      chalk.red('\n[runStory] Error: No story ID provided.\n') +
      chalk.yellow('Usage: npx ts-node scripts/runStory.ts <storyId> [--project=chromium]\n')
    );
    process.exit(1);
  }

  const getArg = (prefix: string): string | undefined =>
    args.find((a) => a.startsWith(prefix))?.split('=')[1];

  return {
    storyId:     parseInt(storyArg, 10),
    project:     getArg('--project=') ?? 'chromium',
    headed:      args.includes('--headed'),
    updateExcel: !args.includes('--no-excel'),
    updateAdo:   !args.includes('--no-ado'),
    dryRun:      args.includes('--dry-run'),
    targetUrl:   getArg('--url='),
  };
}

// ─── Banner ───────────────────────────────────────────────────────────────────

function printBanner(opts: RunOptions): void {
  console.log(chalk.blueBright('\n╔══════════════════════════════════════════════════════════╗'));
  console.log(chalk.blueBright('║         sketchplay-qa-agent — Story Runner               ║'));
  console.log(chalk.blueBright('╚══════════════════════════════════════════════════════════╝'));
  console.log(chalk.cyan(`  Story ID:  #${opts.storyId}`));
  console.log(chalk.cyan(`  Project:   ${opts.project}`));
  if (opts.targetUrl) console.log(chalk.cyan(`  URL:       ${opts.targetUrl}`));
  console.log(chalk.yellow('  Note:      This command reuses the latest generated test-case Excel; it does not regenerate test cases.'));
  console.log(chalk.yellow(`             To regenerate after changing rules, run: npm run analyze:story -- ${opts.storyId}`));
  if (opts.dryRun)    console.log(chalk.yellow('  Mode:      DRY RUN\n'));
  else                console.log(chalk.green('  Mode:      LIVE\n'));
}

let stepIndex = 0;
function step(label: string): void {
  stepIndex++;
  console.log(chalk.bold.white(`\nStep ${stepIndex}: ${label}`));
  console.log(chalk.grey('─'.repeat(60)));
}

// ─── Manifest Loader ──────────────────────────────────────────────────────────

function findLatestManifest(storyId: number): string | null {
  if (!fs.existsSync(EXCEL_DIR)) return null;

  const files = fs.readdirSync(EXCEL_DIR)
    .filter((f) => f.startsWith(`manifest_story${storyId}`) && f.endsWith('.json'))
    .sort()
    .reverse();

  return files.length > 0 ? path.join(EXCEL_DIR, files[0]) : null;
}

function findLatestExcel(storyId: number): string | null {
  if (!fs.existsSync(EXCEL_DIR)) return null;

  const files = fs.readdirSync(EXCEL_DIR)
    .filter((f) => f.startsWith(`TC_Story${storyId}_`) && f.endsWith('.xlsx'))
    .sort()
    .reverse();

  return files.length > 0 ? path.join(EXCEL_DIR, files[0]) : null;
}

// ─── Playwright Execution ─────────────────────────────────────────────────────

async function runPlaywright(opts: RunOptions): Promise<string> {
  step(`Running Playwright tests (project: ${opts.project})`);

  const manifestPath = findLatestManifest(opts.storyId);
  if (!manifestPath) {
    throw new Error(
      `[runStory] No manifest found for Story #${opts.storyId}. Run analyze:story first.`
    );
  }
  const manifest = validateStoryManifest(
    JSON.parse(fs.readFileSync(manifestPath, 'utf-8')) as unknown,
    opts.storyId
  );
  const mappedCases = mappedTestCases(manifest);
  const selectionArgs = buildPlaywrightSelectionArgs(mappedCases);

  const reportJson = path.join(EXCEL_DIR, `pw-results-story${opts.storyId}-${Date.now()}.json`);
  fs.mkdirSync(EXCEL_DIR, { recursive: true });

  const pwArgs: string[] = [
    'test',
    `--project=${opts.project}`,
    '--reporter=json',
    `--output=${path.resolve('test-artifacts/playwright-output')}`,
    ...selectionArgs,
  ];

  if (opts.headed) pwArgs.push('--headed');

  // Pass story ID as env var for fixture consumption
  const env: NodeJS.ProcessEnv = {
    ...process.env,
    STORY_ID: String(opts.storyId),
    PLAYWRIGHT_JSON_OUTPUT_FILE: reportJson,
  };
  if (opts.targetUrl) env['WEB_BASE_URL'] = opts.targetUrl;

  const playwrightCli = path.resolve('node_modules/@playwright/test/cli.js');
  console.log(chalk.grey(`  Command: ${process.execPath} ${playwrightCli} ${pwArgs.join(' ')}`));
  console.log(chalk.grey(`  Results: ${reportJson}\n`));

  // Playwright exits non-zero on failures — we capture the JSON regardless
  const result = spawnSync(process.execPath, [playwrightCli, ...pwArgs], {
    env,
    stdio:       ['inherit', 'pipe', 'inherit'],
    encoding:    'utf-8',
    shell:       false,
    maxBuffer:   50 * 1024 * 1024, // 50MB
  });

  if (result.error) {
    throw new Error(`[runStory] Failed to start Playwright: ${result.error.message}`);
  }
  if (!fs.existsSync(reportJson)) {
    throw new Error(
      `[runStory] Playwright did not write its JSON report (exit code ${result.status ?? 'unknown'}).`
    );
  }
  if (result.status !== 0) {
    console.warn(chalk.yellow(`  ⚠ Playwright exited with code ${result.status}; collecting all available test results.`));
  }

  return reportJson;
}

// ─── Result Parsing ───────────────────────────────────────────────────────────

function parseResults(reportPath: string, storyId: number): TestExecutionRecord[] {
  step('Parsing Playwright test results');

  if (!fs.existsSync(reportPath)) {
    throw new Error(`[runStory] Playwright results file not found: ${reportPath}`);
  }

  let report: unknown;
  try {
    report = JSON.parse(fs.readFileSync(reportPath, 'utf-8')) as unknown;
  } catch (error) {
    throw new Error(
      `[runStory] Could not parse Playwright JSON report: ${(error as Error).message}`
    );
  }

  const manifestPath = findLatestManifest(storyId);
  if (!manifestPath) throw new Error(`[runStory] Manifest for Story #${storyId} disappeared before result parsing.`);
  const manifest = validateStoryManifest(
    JSON.parse(fs.readFileSync(manifestPath, 'utf-8')) as unknown,
    storyId
  );
  const records = parsePlaywrightReport(
    report,
    mappedTestCases(manifest),
    process.env.TEST_ENV ?? 'unspecified'
  );

  const passed  = records.filter((r) => r.result === 'Pass').length;
  const failed  = records.filter((r) => r.result === 'Fail').length;
  const skipped = records.filter((r) => r.result === 'Skipped').length;

  console.log(chalk.green(`  ✔ Parsed ${records.length} test result(s)`));
  console.log(chalk.grey(`  Pass: ${passed} | Fail: ${failed} | Skipped: ${skipped}`));

  return records;
}

// ─── Excel Update ─────────────────────────────────────────────────────────────

async function updateExcel(
  storyId: number,
  executions: TestExecutionRecord[],
  reporter: ExcelReporter,
  opts: RunOptions
): Promise<string | null> {
  if (!opts.updateExcel || opts.dryRun) {
    console.log(chalk.grey('  [runStory] Excel update skipped.'));
    return findLatestExcel(storyId);
  }

  step('Updating Excel report with execution results');

  const excelPath = findLatestExcel(storyId);
  if (!excelPath) {
    console.warn(chalk.yellow(
      `  No Excel file found for Story #${storyId}. ` +
      'Run analyzeStory.ts first to generate the test case spreadsheet.'
    ));
    return null;
  }

  console.log(chalk.grey(`  Reusing generated test cases from: ${path.basename(excelPath)}`));
  const updatedPath = await reporter.updateWithResults(excelPath, executions);
  console.log(chalk.green(`  ✔ Excel updated: ${path.basename(updatedPath)}`));
  return updatedPath;
}

// ─── Azure DevOps Update ──────────────────────────────────────────────────────

async function updateAzureDevOps(
  storyId: number,
  executions: TestExecutionRecord[],
  excelPath: string | null,
  client: AzureDevOpsClient,
  opts: RunOptions
): Promise<CreatedBug[]> {
  if (!opts.updateAdo || opts.dryRun) {
    console.log(chalk.grey('  [runStory] Azure DevOps update skipped.'));
    return [];
  }

  step('Updating Azure DevOps User Story with execution results');

  const passed  = executions.filter((r) => r.result === 'Pass').length;
  const failed  = executions.filter((r) => r.result === 'Fail').length;
  const skipped = executions.filter((r) => r.result === 'Skipped').length;
  const total   = executions.length;
  const passRate = total > 0 ? Math.round((passed / total) * 100) : 0;
  const runDate  = dayjs().format('YYYY-MM-DD HH:mm:ss');

  const bugs: CreatedBug[] = [];

  // Create bugs for failed tests
  const failedTests = executions.filter((r) => r.result === 'Fail');
  if (failedTests.length > 0) {
    step('Creating bugs for failed tests');

    for (const failure of failedTests) {
      try {
        const bug = await client.createBug({
          parentStoryId:  storyId,
          title:          `[QA Auto] ${failure.testName}`,
          description:    `<p>Test case <strong>${failure.testCaseId || failure.testName}</strong> failed during automated execution.</p>`,
          stepsToReproduce: failure.error ?? 'No error details available.',
          actualResult:   failure.error ?? 'The automated test failed.',
          expectedResult: 'Test should pass without errors.',
          systemInfo:     `Playwright QA Agent — Browser: ${opts.project}`,
          areaPath:       AZURE_DEVOPS_AREA_PATH,
          iterationPath:  AZURE_DEVOPS_ITERATION_PATH,
        }, failure.screenshotPath, failure.videoPath);

          bugs.push(bug);
        console.log(chalk.green(`  ✔ Created Bug ${bug.id}: ${failure.testName}`));
      } catch (e) {
        console.warn(chalk.yellow(`  ⚠ Failed to create bug for "${failure.testName}": ${(e as Error).message}`));
      }
    }
  }

  // Re-upload updated Excel
  if (excelPath && fs.existsSync(excelPath)) {
    try {
      await client.uploadAndAttach(
        storyId,
        excelPath,
        `Test execution results — auto-updated by sketchplay-qa-agent at ${runDate}`
      );
      console.log(chalk.green(`  ✔ Updated Excel attached to Story #${storyId}`));
    } catch (e) {
      console.warn(chalk.yellow(`  ⚠ Excel attachment failed: ${(e as Error).message}`));
    }
  }

  // Build a detailed HTML execution summary
  const failedTestsHtml = failedTests
    .map((r) => `<li><b>${r.testCaseId || r.testName}</b>${r.error ? `: ${r.error.slice(0, 200)}` : ''}</li>`)
    .join('\n');

  const bugsHtml = bugs.length > 0
    ? `<p>🐛 <strong>Created Bug Work Items:</strong> ${bugs.map((bug) => `#${bug.id}`).join(', ')}</p>`
    : '';

  const statusBadge = failed > 0
    ? `<span style="background:#C62828;color:#fff;padding:2px 8px;border-radius:4px;">FAILED</span>`
    : `<span style="background:#1B5E20;color:#fff;padding:2px 8px;border-radius:4px;">PASSED</span>`;

  const commentHtml = `
<h3>🤖 sketchplay-qa-agent — Test Execution Complete ${statusBadge}</h3>
<table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse;">
  <thead>
    <tr style="background:#1E3A5F;color:#fff;">
      <th>Metric</th><th>Value</th>
    </tr>
  </thead>
  <tbody>
    <tr><td><b>Run Date</b></td><td>${runDate}</td></tr>
    <tr><td><b>Project / Browser</b></td><td>${opts.project}</td></tr>
    <tr><td><b>Total Tests</b></td><td>${total}</td></tr>
    <tr><td><b>Passed</b></td><td style="color:#1B5E20;">${passed}</td></tr>
    <tr><td><b>Failed</b></td><td style="color:#C62828;">${failed}</td></tr>
    <tr><td><b>Skipped</b></td><td>${skipped}</td></tr>
    <tr><td><b>Pass Rate</b></td><td>${passRate}%</td></tr>
  </tbody>
</table>
${bugsHtml}
${failed > 0 ? `
<h4>❌ Failed Tests</h4>
<ul>${failedTestsHtml}</ul>
` : '<p>✅ All tests passed successfully.</p>'}
<p><small>Generated by <strong>sketchplay-qa-agent v1.0</strong></small></p>
  `.trim();

  try {
    await client.addComment(storyId, commentHtml);
    console.log(chalk.green(`  ✔ Execution summary posted to Story #${storyId}`));
  } catch (e) {
    console.warn(chalk.yellow(`  ⚠ Comment failed: ${(e as Error).message}`));
  }

  return bugs;
}

// ─── Final Summary ────────────────────────────────────────────────────────────

function printSummary(
  opts: RunOptions,
  executions: TestExecutionRecord[],
  excelPath: string | null,
  startTime: number,
  bugs: CreatedBug[] = []
): StoryRunResult {
  const duration = Date.now() - startTime;
  const passed   = executions.filter((r) => r.result === 'Pass').length;
  const failed   = executions.filter((r) => r.result === 'Fail').length;
  const skipped  = executions.filter((r) => r.result === 'Skipped').length;

  const result: StoryRunResult = {
    storyId:      opts.storyId,
    totalTests:   executions.length,
    passed,
    failed,
    skipped,
    duration,
    bugsCreated:  bugs,
    executions,
    excelFilePath: excelPath ?? undefined,
  };

  const icon  = failed > 0 ? '⚠' : '✔';
  const color = failed > 0 ? chalk.yellow : chalk.green;

  console.log(chalk.blueBright('\n╔══════════════════════════════════════════════════════════╗'));
  console.log(chalk.blueBright('║                   Execution Complete                     ║'));
  console.log(chalk.blueBright('╚══════════════════════════════════════════════════════════╝'));
  console.log(color(`  ${icon} Story:    #${opts.storyId}`));
  console.log(color(`  ${icon} Passed:   ${passed} / ${executions.length}`));
  if (failed  > 0) console.log(chalk.red(`  ✘ Failed:   ${failed}`));
  if (skipped > 0) console.log(chalk.grey(`  ○ Skipped:  ${skipped}`));
  if (excelPath)   console.log(chalk.cyan(`  📊 Excel:   ${path.basename(excelPath)}`));
  if (bugs.length > 0) console.log(chalk.cyan(`  🐛 Bugs:    ${bugs.map((bug) => `#${bug.id}`).join(', ')}`));
  console.log(chalk.cyan(`  ⏱ Duration: ${(duration / 1000).toFixed(1)}s\n`));

  return result;
}

// ─── Main ─────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  const startTime = Date.now();
  const opts      = parseArgs();

  printBanner(opts);

  const client   = new AzureDevOpsClient();
  const reporter = new ExcelReporter();

  // Run tests
  const reportJson  = await runPlaywright(opts);
  const executions  = parseResults(reportJson, opts.storyId);

  // Update Excel
  const excelPath   = await updateExcel(opts.storyId, executions, reporter, opts);

  // Update Azure DevOps
  const bugIds = await updateAzureDevOps(opts.storyId, executions, excelPath, client, opts);

  // Print summary
  const result = printSummary(opts, executions, excelPath, startTime, bugIds);

  // Write run result manifest for CI consumption
  const resultPath = path.join(EXCEL_DIR, `run-result-story${opts.storyId}-${Date.now()}.json`);
  fs.writeFileSync(resultPath, JSON.stringify(result, null, 2), 'utf-8');
  console.log(chalk.grey(`  Run manifest: ${resultPath}\n`));

  // Exit with non-zero code if any tests failed (useful for CI gates)
  if (result.failed > 0) {
    process.exit(1);
  }
}

// ─── Entry Point ──────────────────────────────────────────────────────────────

main().catch((err) => {
  console.error(chalk.red(`\n[runStory] Fatal error: ${(err as Error).message}`));
  console.error(chalk.grey((err as Error).stack ?? ''));
  process.exit(1);
});
